    User {
        #[batched(loader = "PostsLoader")]
        fn posts(&self) -> Vec<Post> {
            // Batched with other User.posts calls
        }
    }

    Post {
        #[batched(loader = "CommentsLoader")]
        fn comments(&self) -> Vec<Comment> {
            // Batched with other Post.comments calls
        }
    }
}
