### Context Propagation

**Per-Request Context:**

```rust
use graphql_rs::Context;

pub struct RequestContext {
    user: Option<CurrentUser>,
    request_id: String,
    start_time: Instant,
}

impl RequestContext {
    pub fn new() -> Self {
        Self {
            user: None,
            request_id: uuid::Uuid::new_v4().to_string(),
            start_time: Instant::now(),
        }
    }

    pub fn with_user(mut self, user: CurrentUser) -> Self {
        self.user = Some(user);
        self
    }
}

// In HTTP handler
let mut context = Context::new();
let req_ctx = RequestContext::new()
    .with_user(current_user);
context.insert(req_ctx);

// Pass to schema
let request = graphql_rs::Request::new(query)
    .context(context);
```

**Nested Contexts:**

```rust
resolver! {
    Query {
        fn user(id: ID, ctx: &Context) -> User {
            // Access request context
            let req_ctx = ctx.get::<RequestContext>()?;
            log::info!("Request ID: {}", req_ctx.request_id);

            db::get_user(id)
        }
    }

    User {
        fn posts(&self, ctx: &Context) -> Vec<Post> {
            // Request context is propagated
            let req_ctx = ctx.get::<RequestContext>()?;

            // Add field-specific context
            ctx.insert(FieldContext {
                parent_type: "User".to_string(),
                field: "posts".to_string(),
            });

            db::posts_by_user(&self.id)
        }
    }
