### Custom Directives

**Define Custom Directive:**

```rust
use graphql_rs::directive::{Directive, DirectiveDefinition};

#[derive(Debug)]
pub struct CacheDirective {
    ttl: Option<Duration>,
    key: Option<String>,
}

impl Directive for CacheDirective {
    fn name() -> &'static str {
        "cache"
    }

    fn definition() -> DirectiveDefinition {
        DirectiveDefinition::new("cache")
            .description("Cache field results")
            .argument("ttl", "Int", "Time to live in seconds")
            .argument("key", "String", "Custom cache key")
            .location(DirectiveLocation::FieldDefinition)
    }

    fn apply(&self, field: &Field, context: &mut ResolverContext) {
        context.set_cache_strategy(CacheStrategy {
            ttl: self.ttl.unwrap_or(Duration::from_secs(60)),
            key_template: self.key.clone(),
        });
    }
}

// Register directive
let schema = Schema::builder()
    .register_directive::<CacheDirective>()
    .query(Query)
    .build()?;
```

**Use in Schema:**

```graphql
type Query {
  @cache(ttl: 300)
  user(id: ID!): User

  @cache(ttl: 60, key: "users:all")
  users: [User!]!
