### Error Handling Patterns

**Custom Error Types:**

```rust
use graphql_rs::{GraphQLError, ErrorExtensions};

#[derive(Debug)]
pub enum DomainError {
    NotFound(String, String),
    Validation(String, String),
    Authorization(String),
    Database(String),
}

impl Into<GraphQLError> for DomainError {
    fn into(self) -> GraphQLError {
        match self {
            DomainError::NotFound(entity, id) => {
                GraphQLError::builder()
                    .message(format!("{} not found", entity))
                    .extension("code", "NOT_FOUND")
                    .extension("entity", entity)
                    .extension("id", id)
                    .build()
            }
            DomainError::Validation(field, message) => {
                GraphQLError::builder()
                    .message(message)
                    .extension("code", "VALIDATION_ERROR")
                    .extension("field", field)
                    .build()
            }
            DomainError::Authorization(reason) => {
                GraphQLError::builder()
                    .message("Unauthorized")
                    .extension("code", "UNAUTHORIZED")
                    .extension("reason", reason)
                    .build()
            }
            DomainError::Database(msg) => {
                GraphQLError::builder()
                    .message("Internal server error")
                    .extension("code", "INTERNAL_ERROR")
                    .build()
            }
        }
    }
}
```

**Error Propagation:**

```rust
resolver! {
    Query {
        fn user(id: ID) -> Result<User> {
            db::get_user(id)?
                .ok_or_else(|| DomainError::NotFound("User".to_string(), id))
        }
    }

    Mutation {
        fn create_user(input: CreateUserInput) -> Result<User> {
            // Validate
            if input.name.len() < 3 {
                return Err(DomainError::Validation("name".to_string(), "Name too short".to_string()).into());
            }

            // Check authorization
            if !ctx.get::<CurrentUser>()?.is_admin() {
                return Err(DomainError::Authorization("Not an admin".to_string()).into());
            }

            // Create user
            db::create_user(input)
                .map_err(|e| DomainError::Database(e.to_string()))?
        }
    }
}
```

## Performance Optimization

### Query Optimization

**Complexity-Based Limits:**

```rust
pub struct ComplexityCalculator {
    max_complexity: usize,
    default_field_cost: usize,
    list_multiplier: usize,
}

impl ComplexityCalculator {
    pub fn calculate(&self, operation: &Operation) -> usize {
        self.calculate_selections(&operation.selections, 0)
    }

    fn calculate_selections(&self, selections: &[Selection], depth: usize) -> usize {
        selections.iter().map(|sel| {
            match sel {
                Selection::Field(field) => {
                    let mut cost = self.default_field_cost;

                    // Depth penalty
                    cost += depth * 10;

                    // List multiplier
                    if let Some(list_size) = self.estimate_list_size(field) {
                        cost *= list_size;
                    }

                    // Nested fields
                    cost += self.calculate_selections(&field.selections, depth + 1);

                    cost
                }
                Selection::FragmentSpread(spread) => {
                    // Calculate fragment complexity
                    0
                }
                Selection::InlineFragment(fragment) => {
                    self.calculate_selections(&fragment.selections, depth)
                }
            }
        }).sum()
    }

    fn estimate_list_size(&self, field: &Field) -> Option<usize> {
        // Check field type for list wrapper
        // Check arguments like "first", "limit"
        field.arguments.get("first")
            .or(field.arguments.get("limit"))
            .and_then(|v| v.as_i64())
            .map(|n| n as usize)
    }
}
```

**Query Depth Limiting:**

```rust
pub struct DepthValidator {
    max_depth: usize,
}

impl DepthValidator {
    pub fn validate(&self, selections: &[Selection], current_depth: usize) -> ValidationResult {
        if current_depth > self.max_depth {
            return Err(ValidationError::TooDeep(current_depth, self.max_depth));
        }

        for selection in selections {
            match selection {
                Selection::Field(field) => {
                    self.validate(&field.selections, current_depth + 1)?;
                }
                Selection::InlineFragment(fragment) => {
                    self.validate(&fragment.selections, current_depth)?;
                }
                _ => {}
            }
        }

        Ok(())
    }
}
```

### Caching Strategies

**Response Caching:**

```rust
use graphql_rs::cache::{ResponseCache, CacheKey};

pub struct ResponseCache {
    backend: Arc<dyn CacheBackend>,
    ttl: Duration,
}

impl ResponseCache {
    pub async fn get_or_execute<F>(
        &self,
        request: &Request,
        execute: F,
    ) -> Result<Response>
    where
        F: Future<Output = Result<Response>>,
    {
        // Generate cache key from query and variables
        let key = CacheKey::from_request(request);

        // Try cache
        if let Some(cached) = self.backend.get(&key).await {
            return Ok(cached);
        }

        // Execute
        let response = execute.await?;

        // Cache successful responses
        if response.is_ok() {
            self.backend.set(key, response.clone(), self.ttl).await;
        }

        Ok(response)
    }
}
```

**Field-Level Caching:**

```rust
#[async_trait]
pub trait CachedResolver: Resolver {
    async fn resolve_with_cache(
        &self,
        field: &Field,
        ctx: &Context,
        cache: &Cache,
    ) -> Result<Value> {
        let cache_key = format!("{}:{}", field.name, ctx.path());

        // Try cache
        if let Some(value) = cache.get(&cache_key).await {
            return Ok(value);
        }

        // Resolve
        let value = self.resolve(field, ctx).await?;

        // Cache
        cache.set(cache_key, value.clone(), field.ttl()).await;

        Ok(value)
    }
}
```

