use graphql_rs::value::ValuePool;

pub struct ValuePool {
    strings: Vec<String>,
    objects: Vec<HashMap<String, Value>>,
    lists: Vec<Vec<Value>>,
}

impl ValuePool {
    pub fn alloc_string(&mut self, s: &str) -> Value {
