## Federation Support

### Schema Federation

**Define Entity:**

```rust
use graphql_rs::federation::{Entity, EntityResolver};

#[derive(Entity)]
#[graphql(key = "id")]
pub struct User {
    pub id: String,
    pub name: String,
    pub email: String,
}

impl EntityResolver for User {
    fn resolve_entities(representations: Vec<Value>) -> Vec<User> {
        let ids: Vec<String> = representations
            .iter()
            .filter_map(|rep| rep.get("id"))
            .filter_map(|id| id.as_str())
            .map(|s| s.to_string())
            .collect();

        db::users_by_ids(ids)
    }
}
